<?php
namespace App\Commands;
use CodeIgniter\CLI\{BaseCommand,CLI};
final class IkontrolAdminProvision extends BaseCommand {
 protected $group='iKontrol'; protected $name='ikontrol:admin-provision'; protected $usage='ikontrol:admin-provision <name> <email>';
 public function run(array $params){if(count($params)!==2||!filter_var($params[1],FILTER_VALIDATE_EMAIL))throw new \RuntimeException('Datos de administrador inválidos.');$password=rtrim((string)fgets(STDIN),"\r\n");if(strlen($password)<12)throw new \RuntimeException('La contraseña debe tener al menos 12 caracteres.');$email=strtolower($params[1]);$users=model('App\Models\Users_model');$existing=$users->get_one_where(['email'=>$email,'deleted'=>0]);$db=\Config\Database::connect();$db->transStart();if($existing&&$existing->id){if($existing->user_type!=='staff'||!(int)$existing->is_admin||(int)$existing->role_id!==0)throw new \RuntimeException('El usuario existente no es un administrador reparable.');$userId=(int)$existing->id;$operation='ADMIN_REPAIRED';}else{$parts=preg_split('/\s+/',trim($params[0]),2);$userId=$users->ci_save(['first_name'=>$parts[0],'last_name'=>$parts[1]??'','user_type'=>'staff','is_admin'=>1,'role_id'=>0,'email'=>$email,'password'=>password_hash($password,PASSWORD_DEFAULT),'status'=>'active','client_id'=>0,'is_primary_contact'=>0,'job_title'=>'Admin','disable_login'=>0,'gender'=>'male','language'=>'','enable_web_notification'=>1,'enable_email_notification'=>1,'created_at'=>date('Y-m-d H:i:s'),'requested_account_removal'=>0,'deleted'=>0]);$operation='ADMIN_CREATED';}unset($password);if(!$userId||!$db->tableExists('team_member_job_info'))throw new \RuntimeException('No fue posible preparar el administrador completo.');$job=$users->get_job_info($userId);if(!$job||!$job->user_id){$saved=$users->save_job_info(['user_id'=>$userId,'salary'=>0,'salary_term'=>'','date_of_hire'=>date('Y-m-d')]);if(!$saved)throw new \RuntimeException('No fue posible crear team_member_job_info.');}$db->transComplete();if(!$db->transStatus())throw new \RuntimeException('No fue posible crear o reparar el administrador completo.');CLI::write($operation,'green');}
}